INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS', 'ENVI.G2.SOCIAL.OUR_HOME', 'environmental_activities', 2, 'Tell personal items from common items at home and name materials used to clean them', ARRAY['ENVI.G2.SOCIAL.OUR_HOME.a', 'ENVI.G2.SOCIAL.OUR_HOME.b']::text[], 'Tells personal items (toothbrush, comb, towel, underwear, handkerchief, cup for one person) from common items used by everyone (chairs, plates in the cupboard, the table, the broom, the jerrycan), says personal items are not shared, and names materials to clean them: water, soap, ash, a brush, a cloth, sand for scrubbing pots. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.1.1), never as a phone question: c) clean personal and common items using locally available materials.', '["personal or common item","what we clean it with","which item must not be shared"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS', 'environmental_activities', 2, 'Tell family needs from wants, classify them and put needs first', ARRAY['ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.a', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.c', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.d']::text[], 'Says a need is something a family cannot live well without (food, water, shelter, clothing, health care, school) and a want is nice to have (sweets, toys, a television, a new phone, soda); classifies items; and chooses needs first when there is little money. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["need or want","which comes first","sort into needs and wants"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS', 'environmental_activities', 2, 'Identify places in the locality where family needs are met', ARRAY['ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.b']::text[], 'Matches family needs to local places: food at the market, shop or farm; water at a tap, well, river or borehole; health care at a hospital, clinic or dispensary; clothes at a market or tailor; learning at school; worship at a church or mosque; and knows one place can meet several needs. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["where do we get this","match a need to a place","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'ENVI.G2.SOCIAL.OUR_SCHOOL', 'environmental_activities', 2, 'Name ways of keeping the school environment clean', ARRAY['ENVI.G2.SOCIAL.OUR_SCHOOL.a']::text[], 'Names ways of keeping the school clean: put litter in a bin or litter pit, sweep and dust classrooms, slash grass, clean toilets and flush or cover, wash hands after the toilet, pick litter in the compound, water flowers; and says clean school stops disease and is a shared duty. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.1.1), never as a phone question: c) clean the school environment for the well-being of self and others.', '["which action keeps school clean","where litter goes","what tool to use"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'ENVI.G2.SOCIAL.OUR_SCHOOL', 'environmental_activities', 2, 'Identify common accidents at school and how to prevent them', ARRAY['ENVI.G2.SOCIAL.OUR_SCHOOL.b']::text[], 'Names common accidents at school (falls from running, climbing or slippery floors, cuts from broken glass or sharp objects, burns near the kitchen, bumps from swings, being hit by a stone or ball, falling into a pit) and how to prevent them: walk in corridors, keep away from the kitchen fire, report broken glass, use play equipment one at a time, tell a teacher when hurt. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["which accident could happen here","how to prevent it","what to do if hurt"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG', 'environmental_activities', 2, 'Identify the meaning of the colours on the Kenya national flag', ARRAY['ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.a']::text[], 'Names the colours of the Kenya flag in order from the top (black, white, red, white, green) and their meanings: black for the people of Kenya, red for the blood shed in the struggle for independence, green for the land and natural resources, white for peace; the shield and spears for defending freedom. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["what this colour stands for","which colour stands for this","colour the flag correctly"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG', 'environmental_activities', 2, 'Name events when the national anthem is sung and the etiquette when the flag is raised or lowered', ARRAY['ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.b', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.c']::text[], 'Names events when the national anthem is sung (school assemblies, national holidays such as Madaraka Day, Mashujaa Day and Jamhuri Day, sports events, important government occasions) and the etiquette when the flag is raised or lowered: stop and stand still at attention, face the flag, remove caps, keep quiet or sing, never let the flag touch the ground. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["when is the anthem sung","what to do when the flag is raised","right or wrong behaviour"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS', 'ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB', 'environmental_activities', 2, 'Outline child rights and responsibilities at home and in school', ARRAY['ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.a']::text[], 'Names child rights (food, shelter, clothing, education, health care, play, a name, love and care, protection from harm) and child responsibilities at home and school (obey parents and teachers, do homework, help with simple chores, keep clean, care for property, respect others), and says rights come with responsibilities. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.1.1), never as a phone question: b) carry out the responsibilities of a child at home and in school.', '["right or responsibility","which right is this","what is a child''s responsibility here"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY', 'ENVI.G2.SOCIAL.OUR_MARKET', 'environmental_activities', 2, 'Identify physical features on the way to a local market and use them to locate it', ARRAY['ENVI.G2.SOCIAL.OUR_MARKET.a', 'ENVI.G2.SOCIAL.OUR_MARKET.b']::text[], 'Names physical features on the way to a local market (hills, valleys, rivers, bridges, roads, paths, big trees, buildings such as a church, school or shops) and uses them to give or follow directions to the market (go past the bridge, turn at the big tree, the market is after the church). Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["which feature do you pass","follow the directions","natural or built feature"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES', 'ENVI.G2.SOCIAL.OUR_MARKET', 'environmental_activities', 2, 'Identify activities that take place in a market', ARRAY['ENVI.G2.SOCIAL.OUR_MARKET.c']::text[], 'Names market activities: buying and selling, bargaining over price, weighing goods, loading and transporting goods (by handcart, boda boda, lorry), displaying goods, cleaning the market, collecting market fees; and the people who do them. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["what is this person doing","which activity happens in a market","who does it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.NATURA.WEATHER.WEATHER_TIMES', 'ENVI.G2.NATURA.WEATHER', 'environmental_activities', 2, 'Identify and predict weather conditions at different times of the day and read weather symbols', ARRAY['ENVI.G2.NATURA.WEATHER.a', 'ENVI.G2.NATURA.WEATHER.c']::text[], 'Identifies weather at different times of the day (a cool morning, sometimes misty or cloudy; a hot sunny afternoon; a cool, sometimes windy evening; rainy or cloudy days), reads weather symbols (sun, cloud, raindrops, wind lines, sun behind a cloud), and predicts from signs (dark clouds and wind mean rain may come). Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.2.1, ENVI.G2.RUBRIC.2.2, ENVI.G2.RUBRIC.2.3), never as a phone question: b) create a weather record, using weather symbols.', '["what is the weather in the picture","which symbol shows it","what weather is coming"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.NATURA.SOIL.SOIL_KINDS', 'ENVI.G2.NATURA.SOIL', 'environmental_activities', 2, 'Identify and classify the types of soil found in the locality', ARRAY['ENVI.G2.NATURA.SOIL.a', 'ENVI.G2.NATURA.SOIL.b']::text[], 'Identifies sand, clay and loam in the locality and classifies them by the soil-ribbon test and particle size: clay makes a long smooth ribbon and has tiny particles; loam makes a short ribbon and is crumbly; sand makes no ribbon, falls apart and has big particles. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.2.1, ENVI.G2.RUBRIC.2.2, ENVI.G2.RUBRIC.2.3), never as a phone question: c) make items from soil.', '["which soil is this","which makes the longest ribbon","sort by particle size"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES', 'ENVI.G2.NATURA.LIGHT', 'environmental_activities', 2, 'Identify sources of light and ways of conserving light', ARRAY['ENVI.G2.NATURA.LIGHT.a', 'ENVI.G2.NATURA.LIGHT.c']::text[], 'Identifies sources of light: natural (the sun, stars, fire, lightning) and made by people (bulbs, torches, candles, lanterns, phone screens); knows the moon only reflects the sun''s light; describes ways of conserving light: switch off lights when not in use and during the day, open windows to use daylight, use solar lamps. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.2.1, ENVI.G2.RUBRIC.2.2, ENVI.G2.RUBRIC.2.3), never as a phone question: b) manipulate objects in the presence of light to form shadows for enjoyment.', '["is this a source of light","natural or made by people","how to save light"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.RESOUR.WATER.WATER_STORAGE', 'ENVI.G2.RESOUR.WATER', 'environmental_activities', 2, 'Identify ways of storing water and say why water must be kept safe', ARRAY['ENVI.G2.RESOUR.WATER.a', 'ENVI.G2.RESOUR.WATER.c']::text[], 'Names ways of storing water at home and school (tanks, jerrycans, drums, clay pots, buckets with lids, bottles) and states why water must be kept safe for people and animals: covered, clean containers keep out dust, insects and germs that cause diseases such as cholera and typhoid. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.3.1), never as a phone question: b) conserve water at home and school for future use.', '["which container keeps water safe","why cover the water","what happens if dirty water is drunk"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'ENVI.G2.RESOUR.PLANTS', 'environmental_activities', 2, 'Identify ways of caring for plants using locally available materials', ARRAY['ENVI.G2.RESOUR.PLANTS.a']::text[], 'Names ways of caring for plants with local materials: watering (with a can, a bottle with holes, saved water), manuring (animal dung, compost), mulching (dry grass, leaves), weeding, fencing with sticks or thorns to keep animals away, and not plucking leaves or breaking branches. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.3.1), never as a phone question: b) perform plant-care activities using locally available materials.', '["what this child is doing for the plant","what material to use","helps or harms the plant"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'ENVI.G2.RESOUR.ANIMALS', 'environmental_activities', 2, 'Identify food items from animals and relate each to the animal that gives it', ARRAY['ENVI.G2.RESOUR.ANIMALS.a', 'ENVI.G2.RESOUR.ANIMALS.b']::text[], 'Names food items from animals (milk, eggs, meat, fish, honey, ghee, butter, omena) and relates each to its animal: milk from cows, goats and camels; eggs from hens, ducks and quails; meat from cattle, goats, sheep, chicken, rabbits; fish from lakes and rivers; honey from bees. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G2.RUBRIC.3.1), never as a phone question: c) carry out activities of caring for animals in the locality.', '["which animal gives this","which food comes from this animal","from an animal or a plant"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
