INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.b', 'outcome', 'essential', 'Classifying items and structures as basic needs. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'skill', 'essential', 'Knowing what a need is comes before where it is met. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG', 'skill', 'essential', 'Food items found in a market. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'skill', 'essential', 'Cleaning activities at home come before the school. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'ENVI.G1.SOCIAL.OUR_HOME.a', 'outcome', 'essential', 'Materials used to clean. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'skill', 'essential', 'Common accidents at home come before accidents at school. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'skill', 'essential', 'A clean, tidy school removes many causes of accidents. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS', 'ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'skill', 'essential', 'Main features seen at school, where the flag flies. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
