INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'ENVI.G1.RESOUR.PLANTS.PLANT_PARTS', 'skill', 'essential', 'Activities that conserve plants, from Grade 1. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'ENVI.G1.RESOUR.PLANTS.a', 'outcome', 'essential', 'Parts of a plant: roots take in water. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'skill', 'essential', 'Domestic animals used as food, from Grade 1. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'skill', 'essential', 'Food from plants and animals eaten at home. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS.M_E2_HOME_SHARE_BRUSH', 'ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS', 'Thinks a toothbrush can be shared with a brother or sister if it is rinsed.', '{"question":"Can you share your toothbrush with your sister?","wrong_answer":"Yes, if we rinse it","correct_answer":"No, a toothbrush is a personal item"}'::jsonb, 'Sharing is praised at home, so sharing everything seems kind.', 'Offer "Yes, if we rinse it" beside "No, a toothbrush is a personal item" and ask the child to choose.', 'Sort items into "mine only" and "for everyone". Say: some things carry germs from one mouth to another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS.M_E2_HOME_COMMON_MINE', 'ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS', 'Calls an item personal because he uses it most, such as the family chair he likes.', '{"question":"Is the sofa at home a personal item or a common item?","wrong_answer":"Personal, I sit on it","correct_answer":"Common, everyone uses it"}'::jsonb, 'The child thinks "personal" means "the one I like" or "I use".', 'Offer "Personal, I sit on it" beside "Common, everyone uses it" and ask the child to choose.', 'Ask: who else uses it? If many people use it, it is common.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS.M_E2_HOME_WATER_ONLY', 'ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS', 'Thinks water alone is enough to clean greasy plates and dirty clothes.', '{"question":"What do you need to clean an oily plate?","wrong_answer":"Only water","correct_answer":"Water and soap (or ash)"}'::jsonb, 'Water makes things look wet and clean.', 'Offer "Only water" beside "Water and soap (or ash)" and ask the child to choose.', 'Wash one oily plate with water only and one with soap. Feel both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS.M_E2_HOME_TOWEL_COMMON', 'ENVI.G2.SOCIAL.OUR_HOME.HOME_ITEMS', 'Thinks a towel is a common item because it hangs in a shared place.', '{"question":"Is your bathing towel a personal or common item?","wrong_answer":"Common, it hangs where everyone bathes","correct_answer":"Personal"}'::jsonb, 'Where an item is kept decides, for the child, whose it is.', 'Offer "Common, it hangs where everyone bathes" beside "Personal" and ask the child to choose.', 'Ask what the towel touches: your body. Items that touch the body are personal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS.M_E2_NEED_WANT_LIKE', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'Thinks anything he likes very much is a need.', '{"question":"Is a sweet a need or a want?","wrong_answer":"A need, I like sweets","correct_answer":"A want"}'::jsonb, 'For a young child, wanting something strongly feels the same as needing it.', 'Offer "A need, I like sweets" beside "A want" and ask the child to choose.', 'Ask: can we live well without it? Sort sweets, water, a toy and a blanket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS.M_E2_NEED_EXPENSIVE', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'Thinks expensive items are needs and cheap items are wants.', '{"question":"Which is a need: a television or a bag of maize flour?","wrong_answer":"The television, it costs more","correct_answer":"Maize flour"}'::jsonb, 'Big prices make an item seem important.', 'Offer "The television, it costs more" beside "Maize flour" and ask the child to choose.', 'Compare prices and ask which we need to eat today. Price does not decide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS.M_E2_NEED_WANT_FIRST', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'Chooses a want first when there is only a little money.', '{"question":"Mother has 100 shillings. Should she buy soda or vegetables for supper?","wrong_answer":"Soda","correct_answer":"Vegetables for supper"}'::jsonb, 'The child picks what is most exciting now.', 'Offer "Soda" beside "Vegetables for supper" and ask the child to choose.', 'Role-play shopping with play money: needs first, then a want if money is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS.M_E2_NEED_SCHOOL_WANT', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS', 'Thinks school is a want, not a need, because some children do not go.', '{"question":"Is going to school a need or a want?","wrong_answer":"A want","correct_answer":"A need"}'::jsonb, 'The child has seen children out of school and thinks it is optional.', 'Offer "A want" beside "A need" and ask the child to choose.', 'Say: every child needs to learn, it is a child''s right too. Link with Child Rights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES.M_E2_PLACE_SHOP_ALL', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'Thinks every need is met at a shop, including health care and learning.', '{"question":"Where does a sick child go to get treated?","wrong_answer":"A shop, to buy medicine","correct_answer":"A clinic or hospital"}'::jsonb, 'The child has seen medicine bought at a chemist and thinks shops do everything.', 'Offer "A shop, to buy medicine" beside "A clinic or hospital" and ask the child to choose.', 'Match cards: clinic and nurse, school and teacher, shop and food. A nurse checks the child first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES.M_E2_PLACE_FOOD_SHOP', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'Thinks food comes only from shops, not from farms and gardens.', '{"question":"Where else can a family get sukuma wiki apart from the shop?","wrong_answer":"Nowhere, only the shop","correct_answer":"From their own garden or a farm"}'::jsonb, 'A town child sees food only in shops.', 'Offer "Nowhere, only the shop" beside "From their own garden or a farm" and ask the child to choose.', 'Show a kitchen garden and a farm. Food grows first, then reaches the shop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES.M_E2_PLACE_ONE_NEED', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'Thinks each place meets only one need.', '{"question":"Which needs can a market meet?","wrong_answer":"Only food","correct_answer":"Food, clothes and household items"}'::jsonb, 'Matching games pair one item with one place.', 'Offer "Only food" beside "Food, clothes and household items" and ask the child to choose.', 'Walk through a picture of a market: food, clothes, utensils. One place, many needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES.M_E2_PLACE_WATER_TAP', 'ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEED_PLACES', 'Thinks water comes only from a tap.', '{"question":"Name a place apart from a tap where families get water.","wrong_answer":"There is none","correct_answer":"A well, borehole, river or water tank"}'::jsonb, 'Many children see only taps at school.', 'Offer "There is none" beside "A well, borehole, river or water tank" and ask the child to choose.', 'Show pictures of a borehole, a well, a river and a roof tank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN.M_E2_CLEAN_WORKER_JOB', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'Thinks cleaning the school is only the job of the school workers.', '{"question":"Who should keep our classroom clean?","wrong_answer":"Only the cleaner","correct_answer":"All of us, pupils and workers"}'::jsonb, 'The child sees paid workers sweeping and thinks it is not his duty.', 'Offer "Only the cleaner" beside "All of us, pupils and workers" and ask the child to choose.', 'Make a class duty rota. Everyone keeps the class clean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN.M_E2_CLEAN_LITTER_GROUND', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'Thinks a small sweet paper can be dropped on the ground because it is small.', '{"question":"Where should a sweet paper go?","wrong_answer":"On the ground, it is small","correct_answer":"In the dustbin or litter pit"}'::jsonb, 'One small paper seems to make no difference.', 'Offer "On the ground, it is small" beside "In the dustbin or litter pit" and ask the child to choose.', 'Drop one paper each for the class: count how many. Small litter adds up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN.M_E2_CLEAN_SWEEP_DUST', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'Sweeps without sprinkling water, raising dust, and thinks that is proper cleaning.', '{"question":"Before sweeping a dusty floor, what should you do?","wrong_answer":"Sweep quickly","correct_answer":"Sprinkle a little water first"}'::jsonb, 'Fast sweeping looks hard-working.', 'Offer "Sweep quickly" beside "Sprinkle a little water first" and ask the child to choose.', 'Sweep a dusty corner dry and wet. See the dust cloud. Dust makes us cough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN.M_E2_CLEAN_TOILET_HANDS', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN', 'Thinks hands need washing after the toilet only if they look dirty.', '{"question":"When must you wash your hands at school?","wrong_answer":"Only when they look dirty","correct_answer":"After visiting the toilet and before eating"}'::jsonb, 'Germs cannot be seen.', 'Offer "Only when they look dirty" beside "After visiting the toilet and before eating" and ask the child to choose.', 'Use glitter as "germs" on hands and see how they spread. Wash with soap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS.M_E2_ACC_LUCK', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'Thinks accidents just happen by bad luck and cannot be prevented.', '{"question":"Can we prevent falls in the classroom?","wrong_answer":"No, accidents just happen","correct_answer":"Yes, by walking and keeping the floor dry and clear"}'::jsonb, 'The word accident sounds like something nobody can control.', 'Offer "No, accidents just happen" beside "Yes, by walking and keeping the floor dry and clear" and ask the child to choose.', 'For each accident card, ask: what could we do first so it does not happen?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS.M_E2_ACC_HIDE_HURT', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'Thinks a child who is hurt should hide it so as not to get into trouble.', '{"question":"You cut your hand on a broken window. What do you do?","wrong_answer":"Hide it so I am not punished","correct_answer":"Tell a teacher at once"}'::jsonb, 'The child fears blame for breaking a rule.', 'Offer "Hide it so I am not punished" beside "Tell a teacher at once" and ask the child to choose.', 'Say clearly: when you are hurt, always tell a teacher. You will be helped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS.M_E2_ACC_GLASS_PICK', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'Thinks he should pick up broken glass himself to help.', '{"question":"You see broken glass on the path. What do you do?","wrong_answer":"Pick it up with my hands","correct_answer":"Keep others away and tell a teacher"}'::jsonb, 'Helping is praised, so picking it up seems good.', 'Offer "Pick it up with my hands" beside "Keep others away and tell a teacher" and ask the child to choose.', 'Role-play: stand near, warn friends, call a teacher. Adults pick up glass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS.M_E2_ACC_RUN_SAFE', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_ACCIDENTS', 'Thinks running in corridors is safe if you are careful.', '{"question":"Is it safe to run in the corridor?","wrong_answer":"Yes, if I am careful","correct_answer":"No, walk in the corridor"}'::jsonb, 'Running is fun and the child feels in control.', 'Offer "Yes, if I am careful" beside "No, walk in the corridor" and ask the child to choose.', 'Show how a corner hides someone coming. Practise walking in corridors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS.M_E2_FLAG_RED_DANGER', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS', 'Thinks red on the flag means danger because red means danger on signs.', '{"question":"What does red stand for on the Kenya flag?","wrong_answer":"Danger","correct_answer":"The blood shed in the struggle for independence"}'::jsonb, 'Red on signs and lights means stop or danger.', 'Offer "Danger" beside "The blood shed in the struggle for independence" and ask the child to choose.', 'Tell the short story of the struggle for independence. Red remembers those who died.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS.M_E2_FLAG_GREEN_TREES', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS', 'Thinks green stands only for trees or grass.', '{"question":"What does green stand for on the Kenya flag?","wrong_answer":"Only trees","correct_answer":"The land and its natural resources, including farming"}'::jsonb, 'Green things the child knows are leaves and grass.', 'Offer "Only trees" beside "The land and its natural resources, including farming" and ask the child to choose.', 'Show pictures of farms, forests and wildlife: all part of our land.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS.M_E2_FLAG_ORDER', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS', 'Puts the colours in the wrong order, often with green on top.', '{"question":"Which colour is at the top of the Kenya flag?","wrong_answer":"Green","correct_answer":"Black"}'::jsonb, 'The child remembers the colours but not where each goes.', 'Offer "Green" beside "Black" and ask the child to choose.', 'Colour a flag strip by strip from the top, saying "black, white, red, white, green".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS.M_E2_FLAG_WHITE_NONE', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS', 'Thinks the white stripes are only spaces between colours with no meaning.', '{"question":"What do the white stripes on our flag stand for?","wrong_answer":"Nothing, they are gaps","correct_answer":"Peace"}'::jsonb, 'Thin white lines look like borders in drawings.', 'Offer "Nothing, they are gaps" beside "Peace" and ask the child to choose.', 'Point at each white stripe and say "peace". Ask why peace is placed between the colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE.M_E2_ANTHEM_ANYTIME', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE', 'Thinks the national anthem is a song sung at any time, like a play song.', '{"question":"Is the national anthem sung while playing football at break?","wrong_answer":"Yes, any time","correct_answer":"No, it is sung at special occasions like assemblies and national holidays"}'::jsonb, 'The child knows it as one more song learnt in school.', 'Offer "Yes, any time" beside "No, it is sung at special occasions like assemblies and national holidays" and ask the child to choose.', 'List occasions on the board. Say: the anthem is for important moments.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE.M_E2_FLAG_KEEP_WALKING', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE', 'Thinks you may keep walking or playing while the flag is raised if you are far away.', '{"question":"The flag is being raised and you are walking to class. What do you do?","wrong_answer":"Keep walking","correct_answer":"Stop, face the flag and stand still"}'::jsonb, 'Being far away seems to make it not matter.', 'Offer "Keep walking" beside "Stop, face the flag and stand still" and ask the child to choose.', 'Practise in the field: when the flag goes up, everyone freezes and faces it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE.M_E2_FLAG_GROUND_OK', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE', 'Thinks the flag can be put on the ground while folding it.', '{"question":"Can the flag touch the ground?","wrong_answer":"Yes, while folding it","correct_answer":"No, the flag should never touch the ground"}'::jsonb, 'Other cloths are spread on the ground to fold them.', 'Offer "Yes, while folding it" beside "No, the flag should never touch the ground" and ask the child to choose.', 'Fold a flag in pairs, held off the ground. Say: we show it respect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE.M_E2_ANTHEM_CAP_ON', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_ETIQUETTE', 'Thinks caps and hats may stay on during the anthem.', '{"question":"What do you do with your hat when the anthem is sung?","wrong_answer":"Keep it on","correct_answer":"Take it off"}'::jsonb, 'The child has not noticed others removing caps.', 'Offer "Keep it on" beside "Take it off" and ask the child to choose.', 'Show a picture of an assembly with caps removed. Practise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS.M_E2_RIGHT_RESP_MIX', 'ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS', 'Mixes up rights and responsibilities, calling doing homework a right.', '{"question":"Is doing homework a right or a responsibility?","wrong_answer":"A right","correct_answer":"A responsibility"}'::jsonb, 'Both words are new and taught together.', 'Offer "A right" beside "A responsibility" and ask the child to choose.', 'A right is what I should get; a responsibility is what I should do. Sort cards with the two words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS.M_E2_RIGHT_ANYTHING', 'ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS', 'Thinks a right means getting anything one asks for.', '{"question":"Is getting a new toy every week a child''s right?","wrong_answer":"Yes, I have a right to toys","correct_answer":"No, toys are a want; rights are things like food, school and safety"}'::jsonb, 'The child hears "my right" used to demand things.', 'Offer "Yes, I have a right to toys" beside "No, toys are a want; rights are things like food, school and safety" and ask the child to choose.', 'Link rights to needs: food, shelter, school, care, safety. Wants are not rights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS.M_E2_RIGHT_PLAY_NONE', 'ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS', 'Thinks play is not a right because it is not work or learning.', '{"question":"Is play a child''s right?","wrong_answer":"No, play is wasting time","correct_answer":"Yes, play is a right"}'::jsonb, 'Children are often told to stop playing and work.', 'Offer "No, play is wasting time" beside "Yes, play is a right" and ask the child to choose.', 'Say: play helps children grow and be healthy. Show the right to play on the chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS.M_E2_RIGHT_NO_RESP', 'ENVI.G2.SOCIAL.OUR_RIGHTS_AND_RESPONSIB.RIGHTS', 'Thinks children have only rights and no responsibilities.', '{"question":"Do children have responsibilities?","wrong_answer":"No, only adults do","correct_answer":"Yes, like obeying parents and doing homework"}'::jsonb, 'Children are cared for by adults and see duties as adult things.', 'Offer "No, only adults do" beside "Yes, like obeying parents and doing homework" and ask the child to choose.', 'List small responsibilities children already do. Praise them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY.M_E2_WAY_MOVING_THINGS', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY', 'Uses moving things (a parked lorry, a cow) as landmarks.', '{"question":"Which is a good feature to find the market: a bridge or a parked lorry?","wrong_answer":"A parked lorry","correct_answer":"A bridge"}'::jsonb, 'The child names what caught his eye on the walk.', 'Offer "A parked lorry" beside "A bridge" and ask the child to choose.', 'Ask: will it be there tomorrow? Good features stay in one place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY.M_E2_WAY_ORDER', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY', 'Lists the right features but in the wrong order along the way.', '{"question":"From school you pass a river, then a church, then reach the market. What do you pass first?","wrong_answer":"The church","correct_answer":"The river"}'::jsonb, 'The child remembers the features as a set, not as a sequence.', 'Offer "The church" beside "The river" and ask the child to choose.', 'Walk a classroom path with cards in order. Then retell it in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY.M_E2_WAY_BUILT_NATURAL', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY', 'Thinks only buildings count as features, not hills and rivers.', '{"question":"Is a hill a physical feature?","wrong_answer":"No, features are buildings","correct_answer":"Yes, a hill is a natural physical feature"}'::jsonb, 'Directions given in town use shops and buildings.', 'Offer "No, features are buildings" beside "Yes, a hill is a natural physical feature" and ask the child to choose.', 'Sort pictures into natural features and built features.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY.M_E2_WAY_LEFT_RIGHT', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY', 'Gives directions without saying which way to turn.', '{"question":"How would you tell a visitor to find the market after the big tree?","wrong_answer":"Go to the tree","correct_answer":"At the big tree, turn left and walk to the market"}'::jsonb, 'Young children assume the listener knows what they know.', 'Offer "Go to the tree" beside "At the big tree, turn left and walk to the market" and ask the child to choose.', 'Play a directions game in class: the listener must find the place only from your words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES.M_E2_MKT_BUY_ONLY', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES', 'Thinks the only activity in a market is buying.', '{"question":"Name another activity in a market apart from buying.","wrong_answer":"There is none","correct_answer":"Selling (bargaining, transporting goods)"}'::jsonb, 'The child goes to market with a parent who buys.', 'Offer "There is none" beside "Selling (bargaining, transporting goods)" and ask the child to choose.', 'Role-play a market: some sell, some carry, some clean, some buy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES.M_E2_MKT_PRICE_FIXED', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES', 'Thinks prices in an open-air market are fixed like in a supermarket.', '{"question":"What is bargaining?","wrong_answer":"Paying the first price","correct_answer":"Talking with the seller to agree on a lower price"}'::jsonb, 'Price tags in shops seem to be the rule everywhere.', 'Offer "Paying the first price" beside "Talking with the seller to agree on a lower price" and ask the child to choose.', 'Act out a seller and a buyer agreeing a price for tomatoes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES.M_E2_MKT_TRANSPORT_NONE', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES', 'Thinks goods appear in the market without anyone bringing them.', '{"question":"How do cabbages get to the market?","wrong_answer":"They are already there","correct_answer":"Farmers or traders carry them by cart, boda boda or lorry"}'::jsonb, 'The child sees only the final stall.', 'Offer "They are already there" beside "Farmers or traders carry them by cart, boda boda or lorry" and ask the child to choose.', 'Trace a cabbage from farm to market with pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES.M_E2_MKT_CLEAN_NONE', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_ACTIVITIES', 'Thinks nobody cleans the market and rubbish just stays.', '{"question":"Who keeps the market clean?","wrong_answer":"Nobody","correct_answer":"Cleaners employed by the county, and the traders"}'::jsonb, 'The child sees a busy market but not the cleaning at night.', 'Offer "Nobody" beside "Cleaners employed by the county, and the traders" and ask the child to choose.', 'Show a picture of market cleaners and the fees traders pay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.WEATHER.WEATHER_TIMES.M_E2_WEA_SAME_DAY', 'ENVI.G2.NATURA.WEATHER.WEATHER_TIMES', 'Thinks the weather is the same all day once it is sunny in the morning.', '{"question":"It is sunny in the morning. Will it be sunny all day?","wrong_answer":"Yes, all day","correct_answer":"Not always: it can change in the afternoon"}'::jsonb, 'The child notices the weather at one moment only.', 'Offer "Yes, all day" beside "Not always: it can change in the afternoon" and ask the child to choose.', 'Record the weather at 8, 12 and 3 o''clock for a week. Compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.WEATHER.WEATHER_TIMES.M_E2_WEA_CLOUD_RAIN', 'ENVI.G2.NATURA.WEATHER.WEATHER_TIMES', 'Thinks every cloud brings rain.', '{"question":"There are a few white clouds. Will it rain?","wrong_answer":"Yes, clouds bring rain","correct_answer":"Probably not: dark, heavy clouds bring rain"}'::jsonb, 'Rain comes from clouds, so all clouds seem to bring it.', 'Offer "Yes, clouds bring rain" beside "Probably not: dark, heavy clouds bring rain" and ask the child to choose.', 'Show pictures of light white clouds and dark rain clouds. Sort them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.WEATHER.WEATHER_TIMES.M_E2_WEA_SYMBOL_WIND', 'ENVI.G2.NATURA.WEATHER.WEATHER_TIMES', 'Reads the wind symbol (curved lines) as rain or as nothing.', '{"question":"What does this symbol mean: curved lines blowing sideways?","wrong_answer":"Rain","correct_answer":"Windy"}'::jsonb, 'Lines are read as water falling.', 'Offer "Rain" beside "Windy" and ask the child to choose.', 'Blow on a paper strip and draw what you see. Compare with the rain symbol of drops falling down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.WEATHER.WEATHER_TIMES.M_E2_WEA_MORNING_HOT', 'ENVI.G2.NATURA.WEATHER.WEATHER_TIMES', 'Thinks mornings are the hottest part of the day because the sun has just come out.', '{"question":"When is it usually hottest: morning or afternoon?","wrong_answer":"Morning","correct_answer":"Afternoon"}'::jsonb, 'The child links the sun appearing with heat.', 'Offer "Morning" beside "Afternoon" and ask the child to choose.', 'Feel the ground or a wall in the morning and after lunch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.SOIL.SOIL_KINDS.M_E2_SOIL_COLOUR_TYPE', 'ENVI.G2.NATURA.SOIL.SOIL_KINDS', 'Names the soil type by colour only (red soil, black soil) and misses how it feels.', '{"question":"How can you tell clay from sand?","wrong_answer":"By colour only","correct_answer":"By how it feels and whether it makes a ribbon"}'::jsonb, 'Soils near home are named by colour.', 'Offer "By colour only" beside "By how it feels and whether it makes a ribbon" and ask the child to choose.', 'Give two soils of the same colour that feel different. Do the ribbon test.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.SOIL.SOIL_KINDS.M_E2_SOIL_RIBBON_SAND', 'ENVI.G2.NATURA.SOIL.SOIL_KINDS', 'Thinks sand makes the longest ribbon because it has the most grains.', '{"question":"Which soil makes the longest ribbon?","wrong_answer":"Sand","correct_answer":"Clay"}'::jsonb, 'More grains seem to make more ribbon.', 'Offer "Sand" beside "Clay" and ask the child to choose.', 'Roll wet sand and wet clay. Sand breaks; clay stretches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.SOIL.SOIL_KINDS.M_E2_SOIL_PARTICLE_BIG', 'ENVI.G2.NATURA.SOIL.SOIL_KINDS', 'Thinks clay has the biggest particles because it sticks in big lumps.', '{"question":"Which soil has the biggest particles?","wrong_answer":"Clay, it is in big lumps","correct_answer":"Sand"}'::jsonb, 'Lumps are taken for particles.', 'Offer "Clay, it is in big lumps" beside "Sand" and ask the child to choose.', 'Rub each soil between the fingers and look with a hand lens. Sand grains are big and seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.SOIL.SOIL_KINDS.M_E2_SOIL_TWO_TYPES', 'ENVI.G2.NATURA.SOIL.SOIL_KINDS', 'Thinks there are only two types of soil: sand and mud.', '{"question":"Name three types of soil.","wrong_answer":"Sand and mud","correct_answer":"Sand, clay and loam"}'::jsonb, 'Wet soil is called mud at home.', 'Offer "Sand and mud" beside "Sand, clay and loam" and ask the child to choose.', 'Show three samples side by side and name each. Mud is wet soil of any type.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES.M_E2_LIGHT_MOON', 'ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES', 'Thinks the moon makes its own light.', '{"question":"Does the moon make its own light?","wrong_answer":"Yes, it shines at night","correct_answer":"No, it reflects light from the sun"}'::jsonb, 'The moon looks bright like a lamp.', 'Offer "Yes, it shines at night" beside "No, it reflects light from the sun" and ask the child to choose.', 'Shine a torch on a ball in a dark room. The ball looks bright but makes no light.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES.M_E2_LIGHT_MIRROR', 'ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES', 'Thinks a mirror or shiny tin is a source of light because it shines.', '{"question":"Is a mirror a source of light?","wrong_answer":"Yes, it shines","correct_answer":"No, it only reflects light"}'::jsonb, 'Shiny things look bright.', 'Offer "Yes, it shines" beside "No, it only reflects light" and ask the child to choose.', 'Put a mirror in a dark box. Does it give light? Then add a torch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES.M_E2_LIGHT_DAY_ON', 'ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES', 'Thinks lights should stay on in the day so the room is bright.', '{"question":"It is a sunny day. Should the classroom lights be on?","wrong_answer":"Yes, it is brighter","correct_answer":"No, open the windows and use daylight"}'::jsonb, 'More light seems always better.', 'Offer "Yes, it is brighter" beside "No, open the windows and use daylight" and ask the child to choose.', 'Switch the lights off and open windows. Can we still see? Say: saving electricity saves money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES.M_E2_LIGHT_SUN_ONLY', 'ENVI.G2.NATURA.LIGHT.LIGHT_SOURCES', 'Thinks the sun is the only source of light.', '{"question":"Name a source of light apart from the sun.","wrong_answer":"There is none","correct_answer":"A bulb (a torch, a candle, fire)"}'::jsonb, 'The sun is taught first as the giver of light.', 'Offer "There is none" beside "A bulb (a torch, a candle, fire)" and ask the child to choose.', 'Darken the room and light a candle and a torch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.WATER.WATER_STORAGE.M_E2_STORE_OPEN', 'ENVI.G2.RESOUR.WATER.WATER_STORAGE', 'Thinks an open bucket stores water as well as a covered one.', '{"question":"Which keeps drinking water safe: an open bucket or a covered jerrycan?","wrong_answer":"An open bucket","correct_answer":"A covered jerrycan"}'::jsonb, 'Water poured in clean seems to stay clean.', 'Offer "An open bucket" beside "A covered jerrycan" and ask the child to choose.', 'Leave an open and a covered cup for a day. Look at dust and insects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.WATER.WATER_STORAGE.M_E2_STORE_DIRTY_JERRYCAN', 'ENVI.G2.RESOUR.WATER.WATER_STORAGE', 'Thinks a jerrycan never needs washing because only water goes in it.', '{"question":"Should a water jerrycan be washed?","wrong_answer":"No, only water goes in","correct_answer":"Yes, it should be washed often"}'::jsonb, 'The child cannot see the slime inside.', 'Offer "No, only water goes in" beside "Yes, it should be washed often" and ask the child to choose.', 'Shine a torch into an old jerrycan. Show the green slime. Wash it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.WATER.WATER_STORAGE.M_E2_STORE_ANIMALS_ANY', 'ENVI.G2.RESOUR.WATER.WATER_STORAGE', 'Thinks animals can drink any dirty water.', '{"question":"Do animals need safe water too?","wrong_answer":"No, animals drink anything","correct_answer":"Yes, dirty water can make animals sick too"}'::jsonb, 'Animals drink from puddles, so it seems fine for them.', 'Offer "No, animals drink anything" beside "Yes, dirty water can make animals sick too" and ask the child to choose.', 'Talk about cows getting sick from dirty water. Show a clean trough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.WATER.WATER_STORAGE.M_E2_STORE_DISEASE_NONE', 'ENVI.G2.RESOUR.WATER.WATER_STORAGE', 'Does not link dirty stored water with illness.', '{"question":"What can happen if you drink dirty water?","wrong_answer":"Nothing","correct_answer":"You can get sick, with diseases like cholera or typhoid"}'::jsonb, 'Illness comes later and is not linked to the water.', 'Offer "Nothing" beside "You can get sick, with diseases like cholera or typhoid" and ask the child to choose.', 'Tell a short story of a family who got sick from uncovered water. Link cause and effect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE.M_E2_PLANT_WATER_LEAVES', 'ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'Thinks plants should be watered on the leaves, not at the roots.', '{"question":"Where should you pour water when watering a plant?","wrong_answer":"On the leaves","correct_answer":"On the soil near the roots"}'::jsonb, 'The child sees the leaves as the plant and wants them wet.', 'Offer "On the leaves" beside "On the soil near the roots" and ask the child to choose.', 'Draw the roots under the soil. Say: roots drink the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE.M_E2_PLANT_MORE_WATER', 'ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'Thinks more water is always better, even flooding a pot.', '{"question":"Is it good to pour water until the pot overflows every hour?","wrong_answer":"Yes, plants love water","correct_answer":"No, too much water can rot the roots"}'::jsonb, 'Water helps plants, so more seems to help more.', 'Offer "Yes, plants love water" beside "No, too much water can rot the roots" and ask the child to choose.', 'Watch a flooded seedling wilt. Water a little each morning or evening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE.M_E2_PLANT_DUNG_DIRTY', 'ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'Thinks animal dung harms plants because it is dirty.', '{"question":"Is cow dung good or bad for plants?","wrong_answer":"Bad, it is dirty","correct_answer":"Good, it is manure that feeds plants"}'::jsonb, 'Dung is called dirty at home.', 'Offer "Bad, it is dirty" beside "Good, it is manure that feeds plants" and ask the child to choose.', 'Grow two bean plants, one with manure. Compare after two weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.PLANTS.PLANT_CARE.M_E2_PLANT_MULCH_RUBBISH', 'ENVI.G2.RESOUR.PLANTS.PLANT_CARE', 'Thinks dry grass around a plant is rubbish to be cleared away.', '{"question":"Why do farmers put dry grass around plants?","wrong_answer":"They forgot to clear it","correct_answer":"To keep the soil wet and stop weeds (mulching)"}'::jsonb, 'A tidy, bare garden looks cared for.', 'Offer "They forgot to clear it" beside "To keep the soil wet and stop weeds (mulching)" and ask the child to choose.', 'Feel the soil under mulch and bare soil at noon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS.M_E2_AFOOD_MILK_COW', 'ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'Thinks only cows give milk.', '{"question":"Which other animals give milk apart from cows?","wrong_answer":"None","correct_answer":"Goats and camels"}'::jsonb, 'Cow''s milk is the only milk most children see.', 'Offer "None" beside "Goats and camels" and ask the child to choose.', 'Show pictures of goat and camel milk in northern Kenya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS.M_E2_AFOOD_HONEY_PLANT', 'ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'Thinks honey comes from flowers or trees, not from an animal.', '{"question":"Which animal gives us honey?","wrong_answer":"None, it comes from trees","correct_answer":"Bees"}'::jsonb, 'Honey is collected from hives in trees and bees use flowers.', 'Offer "None, it comes from trees" beside "Bees" and ask the child to choose.', 'Show a beehive picture: bees make honey from flower nectar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS.M_E2_AFOOD_EGGS_DUCK', 'ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'Thinks eggs come only from hens.', '{"question":"Do ducks lay eggs that people eat?","wrong_answer":"No, only hens","correct_answer":"Yes"}'::jsonb, 'Shop eggs are hen eggs.', 'Offer "No, only hens" beside "Yes" and ask the child to choose.', 'Show hen, duck and quail eggs. Many birds lay eggs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS.M_E2_AFOOD_BUTTER_PLANT', 'ENVI.G2.RESOUR.ANIMALS.ANIMAL_FOODS', 'Thinks butter and ghee come from plants because they are like oil.', '{"question":"Where does ghee come from?","wrong_answer":"A plant, like cooking oil","correct_answer":"Milk from cows or goats"}'::jsonb, 'Ghee is used like cooking oil, which comes from plants.', 'Offer "A plant, like cooking oil" beside "Milk from cows or goats" and ask the child to choose.', 'Show how cream from milk is churned into butter and heated into ghee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
