-- =====================================================================
-- HOREB: Grade 2 Environmental Activities skills, prerequisites and misconceptions (owner, 19 Nov 2026)
-- =====================================================================
-- NOT RUN. Run in Supabase Dashboard -> SQL Editor, after 20261110_curriculum.sql (the five curriculum tables); the Environmental Activities grades in order, 1 to 3 (prerequisites name the grade below; there is no foreign key on them). Idempotent: safe to run twice.
-- WHY: Environmental Activities Grade 2 had KICD outcomes only (curriculum/environmental_activities/g2.json); on 19 Nov 2026 it was mapped to the Grade 5 Maths standard (a skill for every testable outcome, practical outcomes to the teacher's KICD rubric, two or more prerequisites and four misconceptions per skill, a teaching pack). This loads 16 skills (proposed), 32 prerequisites (proposed) and 64 misconceptions (draft)
-- for 12 of 12 sub-strands, for the teacher reviewer. Outcomes are KICD's own words and are not changed.
-- GENERATED by scripts/build-environmental-grade.mjs 2 from curriculum/environmental_activities/g2.json. Do not edit by hand.
-- The sub-strands and outcomes are inserted first (do nothing if present) so the foreign keys hold.
-- =====================================================================
BEGIN;
DELETE FROM public.curriculum_prerequisites WHERE skill_code LIKE 'ENVI.G2.%' AND requires_kind = 'outcome' AND status = 'proposed' AND (skill_code || '|' || requires_code) <> ALL (ARRAY['ENVI.G2.SOCIAL.FAMILY_NEEDS_AND_WANTS.NEEDS_WANTS|ENVI.G1.SOCIAL.FAMILY_NEEDS.b', 'ENVI.G2.SOCIAL.OUR_SCHOOL.SCHOOL_CLEAN|ENVI.G1.SOCIAL.OUR_HOME.a', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.FLAG_COLOURS|ENVI.G1.SOCIAL.OUR_SCHOOL.d', 'ENVI.G2.SOCIAL.OUR_MARKET.MARKET_WAY|ENVI.G1.SOCIAL.OUR_SCHOOL.b', 'ENVI.G2.NATURA.WEATHER.WEATHER_TIMES|ENVI.G1.NATURA.WEATHER_AND_THE_SKY.c', 'ENVI.G2.NATURA.SOIL.SOIL_KINDS|ENVI.G1.NATURA.SOIL.a', 'ENVI.G2.RESOUR.WATER.WATER_STORAGE|ENVI.G1.RESOUR.WATER.b', 'ENVI.G2.RESOUR.PLANTS.PLANT_CARE|ENVI.G1.RESOUR.PLANTS.a']::text[]);
COMMIT;
